AI Inference Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AI Inference Service container

Container_Boundary(ai_inference_service_boundary, "AI Inference Service") {
    Component(ai_inference_engine, "AI Inference Engine", "Python / FastAPI / ONNX Runtime / PyTorch", "Executes localized model inference for the AI symptom checker.")
    Component(safety_guardrail_controller, "Safety Guardrail Controller", "spaCy / Regex", "Performs synchronous safety guardrail checks and keyword filtering on inputs.")
}

Rel(safety_guardrail_controller, ai_inference_engine, "Passes filtered and validated inputs for model execution")

@enduml

Interoperability Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(interoperability_service, "Interoperability Service") {
    Component(FHIR_Translation_Engine, "FHIR Translation Engine", "Java / Spring Boot", "Translates regional health data formats into standard FHIR representations.")
    Component(EU_Gateway_Adapter_Module, "EU Gateway Adapter Module", "Java / Spring Boot", "Adapts payloads for integration with external National E-Prescription Gateways in the EU.")
    Component(Consent_Policy_Enforcement_Interceptor, "Consent & Policy Enforcement Interceptor", "Java / Spring Boot", "Validates consent and enforces regional data access policies.")
    Component(Async_Dispatch_DLQ_Manager, "Async Dispatch & DLQ Manager", "Java / Spring Boot, Resilience4j", "Manages asynchronous dispatch and persistent dead-letter queues for unrecoverable payloads.")
}

Rel(Consent_Policy_Enforcement_Interceptor, FHIR_Translation_Engine, "Dispatches validated payloads", "Spring Application Events")
Rel(Consent_Policy_Enforcement_Interceptor, EU_Gateway_Adapter_Module, "Dispatches validated payloads", "Spring Application Events")

@enduml

Containerized SFUs.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Containerized SFUs container

Container_Boundary(containerized_sfus, "Containerized SFUs") {
    Component(Signaling_Room_Manager, "Signaling & Room Manager", "Node.js / TypeScript", "Manages signaling, room management, and worker lifecycle control via WebSockets and local IPC.")
    Component(Media_Router_Worker_Bandwidth_Adaptation_Engine, "Media Router Worker & Bandwidth Adaptation Engine", "C++ / mediasoup", "High-performance WebRTC media routing and simulcast/SVC stream adaptation for bandwidth resilience.")
}

Rel(Signaling_Room_Manager, Media_Router_Worker_Bandwidth_Adaptation_Engine, "Communicates via local Unix sockets for inter-process communication (IPC)", "Unix Socket")

@enduml
